head.script:
scwin.onpageload = function() {
    //windowContainer1.createWindow( "title1" , null , "/hyundai/gridView_excelUpload.xml" , "windowTitle1" , "windowId1" , "" , "closeAction");
    //windowContainer1.createWindow( "title1" , null , "/hyundai/tabControl_hd.xml" , "windowTitle1" , "windowId1" , "" , "closeAction");
    var xmlArr = [
        "wincon_child.xml",
        "selectbox_autoComplete_checkcombobox.xml",
        "checkcombobox_hd_bak.xml",
        "checkcombobox_hd.xml",
        "gridView_advancedExcelDown.xml",
        "gridView_autoComplete_radio.xml",
        "gridView_checkcombobox_manydata.xml",
        "gridView_checkcombobox.xml"
    ];
    for (var i = 0; i < xmlArr.length; i++) {
        var options = {
            title: (i + 1) + "접수및등록업무화면",
            iconUrl: null,
            src: xmlArr[i],
            windowTitle: "windowTitle" + (i + 1),
            windowId: "windowId" + (i + 1),
            frameMode: "wframe",
        };
        windowContainer1.createWindow(options);
    }
    var options = {
        title: "title2",
        iconUrl: null,
        src: "selectbox_autoComplete_checkcombobox.xml",
        windowTitle: "windowTitle2",
        windowId: "windowId2",
        frameMode: "wframe",
    };
    // windowContainer1.createWindow( options );
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_windowList').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2list_listColumn_close').length == 8", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
